<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserInvitation\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Access\UserInvitation\Domain\ValueObject\UserInvitationEmailVO;

trait UserInvitationEmailAccessor
{
    private UserInvitationEmailVO $_email;
    public function getEmail(): string
    {
        return $this->_email->value();
    }
    public function email(): UserInvitationEmailVO
    {
        return $this->_email;
    }
    public function isEmailChanged(?self $original = null): bool
    {
        return !$this->_email->equals($original?->_email);
    }
    public function withEmail(UserInvitationEmailVO|string $email): self
    {
        $copy = clone $this;
        $copy->_email = UserInvitationEmailVO::from($email);
        return $copy;
    }
}
